probes.origin:
// Can a page fetch a GitHub release asset, or a GitHub Pages file, cross-origin?
import * as cdp from "REPO/scripts/browser-check/cdp.mjs";
import { serve } from "REPO/scripts/browser-check/serve.mjs";
const server = await serve({ root: process.argv[2] });
const chrome = await cdp.launch(process.env.CHROME);
const { page } = chrome;
await page.navigate(`${server.origin}/`);
const urls = {
  release: "https://github.com/formalverification/agda-wasm-builds/releases/download/agda-2.9.0-da66a8c-als-8/SHA256SUMS",
  pages: "https://formalverification.github.io/agda-native-air/assets/images/favicon.png",
};
const out = { browser: chrome.product, origin: server.origin, date: new Date().toISOString(), results: {} };
for (const [name, url] of Object.entries(urls)) {
  await page.eval((url) => { window.__r = "pending"; fetch(url).then(async (r) => { window.__r = { ok: r.ok, status: r.status, bytes: (await r.arrayBuffer()).byteLength, acao: r.headers.get("access-control-allow-origin") }; }, (e) => { window.__r = { error: `${e.name}: ${e.message}` }; }); }, url);
  let r = "pending";
  for (let i = 0; i < 100 && r === "pending"; i++) { await new Promise((d) => setTimeout(d, 100)); r = await page.eval(() => window.__r); }
  out.results[name] = { url, ...r };
}
console.log(JSON.stringify(out, null, 1));
await chrome.close(); await server.close();

probes.importsReading:
// For every module of the index: the closure of the imports read from its
// source, through the index's graph, must be its closure in Agda's graph
// less itself.  Exact reachability is the index's; the reading only has
// to find the imports.
import { readFileSync, existsSync } from "node:fs";
const { sourceKind } = await import(process.argv[2] + "/packages/engine/dist/core/index.js"); const { importedModules } = await import(process.argv[2] + "/packages/manifest/dist/index.js");
const index = JSON.parse(readFileSync(process.argv[3] + "/index.json", "utf8"));
const root = process.argv[4];
const closure = (names) => { const seen = new Set(); const todo = [...names]; while (todo.length) { const n = todo.pop(); if (seen.has(n) || !index.modules[n]) continue; seen.add(n); todo.push(...index.modules[n].deps); } return seen; };
let checked = 0, wrong = [], unknown = new Map();
for (const [name, module] of Object.entries(index.modules)) {
  if (module.library === "builtins") continue;
  const file = module.library === "agda-algebras" ? root + module.source : root + "/stdlibzip/agda-stdlib-2.3" + module.source.replace(/^\/stdlib/, "");
  if (!existsSync(file)) { wrong.push(`${name}: no file ${file}`); continue; }
  const imports = importedModules(readFileSync(file, "utf8"), sourceKind(file));
  if (!imports) { wrong.push(`${name}: unread kind`); continue; }
  for (const i of imports) if (!index.modules[i]) unknown.set(i, (unknown.get(i) ?? 0) + 1);
  const mine = closure(imports);
  const agdas = closure([name]); agdas.delete(name);
  const missing = [...agdas].filter((m) => !mine.has(m));
  const extra = [...mine].filter((m) => !agdas.has(m));
  if (missing.length || extra.length) wrong.push(`${name}: missing ${missing.slice(0, 5)} extra ${extra.slice(0, 5)}`);
  checked++;
}
console.log(JSON.stringify({ checked, wrong: wrong.length, examples: wrong.slice(0, 10), importsNotInIndex: [...unknown] }, null, 1));

probes.browserBuiltInterfaces:
// Does the page's own check of a module from source write the same interface
// bytes as agda-algebras' archives hold?  Seed Main with an import, wait for
// the check and the drive's persist, and read the persisted interfaces back.
import * as cdp from "REPO/scripts/browser-check/cdp.mjs";
import { serve } from "REPO/scripts/browser-check/serve.mjs";
const [site, module] = process.argv.slice(2);
const main = `{-# OPTIONS --without-K --exact-split --safe #-}\n\nmodule Main where\n\nimport ${module}\n`;
const server = await serve({ root: site });
const chrome = await cdp.launch(process.env.CHROME);
const { page } = chrome;
await page.addInitScript(`if (!sessionStorage.getItem("seeded")) { sessionStorage.setItem("seeded", "1"); localStorage.setItem("agda-web-ide-beta:doc:/play/Main.agda", ${JSON.stringify(main)}); }`);
await page.navigate(`${server.origin}/`);
const t0 = Date.now();
let status = "";
while (Date.now() - t0 < 900_000) {
  status = await page.eval(() => document.querySelector(".inspector-status")?.textContent?.trim() ?? "");
  if (/ · \d/.test(status) && !(await page.eval(() => document.querySelector(".spin") !== null))) break;
  await new Promise((d) => setTimeout(d, 500));
}
console.error(`check: ${status} after ${Date.now() - t0} ms; waiting 15 s for the persist`);
await new Promise((d) => setTimeout(d, 15_000));
await page.eval(() => {
  window.__probe = "pending";
  (async () => {
    const names = (await indexedDB.databases()).map((d) => d.name).filter((n) => n.startsWith("agda-playground-drive-"));
    const out = { databases: names, files: [] };
    for (const name of names) {
      const db = await new Promise((ok, no) => { const r = indexedDB.open(name); r.onsuccess = () => ok(r.result); r.onerror = () => no(r.error); });
      const records = await new Promise((ok, no) => { const r = db.transaction("files").objectStore("files").getAll(); r.onsuccess = () => ok(r.result); r.onerror = () => no(r.error); });
      for (const record of records) {
        if (!record.path.endsWith(".agdai")) continue;
        const bytes = record.content instanceof Uint8Array ? record.content : new TextEncoder().encode(record.content);
        const digest = [...new Uint8Array(await crypto.subtle.digest("SHA-256", bytes))].map((b) => b.toString(16).padStart(2, "0")).join("");
        out.files.push({ path: record.path, bytes: bytes.byteLength, sha256: digest });
      }
    }
    window.__probe = out;
  })().catch((e) => (window.__probe = { error: String(e) }));
});
let result = "pending";
for (let i = 0; i < 200 && result === "pending"; i++) { await new Promise((d) => setTimeout(d, 100)); result = await page.eval(() => window.__probe); }
console.log(JSON.stringify({ browser: chrome.product, module, status, ...result }, null, 1));
await chrome.close(); await server.close();

probes.mountTimes:
// Mount times in the page (issue 14): for each import, a fresh profile
// whose stored Main imports it; the automatic check asks; the probe agrees,
// and times the mount (from the answer to the check's start) and the check
// (the page's own duration); then a reload in the same profile, which
// mounts from the browser's store, timed the same way.  Each line is one
// visit.  REPO and CHROME as the timing-checks-in-the-page skill's probes.
import * as cdp from "REPO/scripts/browser-check/cdp.mjs";
import { serve } from "REPO/scripts/browser-check/serve.mjs";
import { readFileSync } from "node:fs";
import { loadavg } from "node:os";
const [site, roundsText, ...modules] = process.argv.slice(2);
const rounds = Number(roundsText);
const RECORDER = readFileSync("REPO/scripts/browser-check/run.mjs", "utf8").match(/const RECORDER = `([\s\S]*?)`;\n/)[1]
  .replaceAll("\\\\", "\\").replace("${JSON.stringify(\"/agda-algebras/interfaces/\")}", '"/agda-algebras/interfaces/"');
const look = () => ({
  status: document.querySelector(".inspector-status")?.textContent?.trim() ?? "",
  consent: document.querySelector(".consent-size")?.dataset.bytes ?? null,
  text: document.querySelector(".consent")?.textContent?.replace(/\s+/g, " ").trim() ?? null,
  busy: document.querySelector(".spin") !== null,
  error: document.querySelector(".action-error span")?.textContent?.trim() ?? null,
  now: performance.now(),
});
const until = async (page, predicate, ms = 600_000) => {
  const start = Date.now();
  for (;;) {
    let s;
    try { s = await page.eval(look); } catch { s = null; }
    if (s?.error) throw new Error(s.error);
    if (s && predicate(s)) return s;
    if (Date.now() - start > ms) throw new Error(`timed out; last ${JSON.stringify(s)}`);
    await new Promise((d) => setTimeout(d, 50));
  }
};
const seconds = (text) => { const m = text.match(/· (?:(\d+)m )?([\d.]+) (ms|s)$/); return m ? (Number(m[1] ?? 0) * 60 + Number(m[2]) / (m[3] === "ms" ? 1000 : 1)) : NaN; };
const results = [];
for (let round = 0; round < rounds; round++) for (const module of modules) {
  const server = await serve({ root: site, noStore: ["/agda-algebras/"] });
  const chrome = await cdp.launch(process.env.CHROME);
  const { page } = chrome;
  await page.setViewport(1440, 900);
  const main = `{-# OPTIONS --without-K --exact-split --safe #-}\n\nmodule Main where\n\nimport ${module}\n`;
  await page.addInitScript(RECORDER);
  await page.addInitScript(`if (!sessionStorage.getItem("seeded")) { sessionStorage.setItem("seeded", "1"); localStorage.setItem("agda-web-ide-beta:doc:/play/Main.agda", ${JSON.stringify(main)}); }`);
  const load = loadavg()[0];
  await page.navigate(`${server.origin}/`);
  const asked = await until(page, (s) => s.consent !== null && !s.busy);
  const answered = await page.eval(() => { document.querySelector(".consent-fetch").click(); return performance.now(); });
  const done = await until(page, (s) => !s.busy && s.consent === null && s.status.startsWith("Module checked"));
  let events = await page.eval(() => window.__browserCheck);
  const checkStart = events.find((e) => e.t >= answered && e.name === "status" && /^Checking source/.test(e.text ?? ""))?.t;
  const ready = events.find((e) => e.name === "bar" && /Agda ready/.test(e.text ?? ""))?.t;
  const cold = server.log.filter((r) => r.url.startsWith("/agda-algebras/interfaces/"));
  results.push({ module, round, visit: "first", load: Number(load.toFixed(2)), stated: Number(asked.consent), archives: cold.length,
    bytes: cold.reduce((a, r) => a + r.bytes, 0), agdaReadyMs: ready, mountMs: Math.round(checkStart - answered),
    checkS: seconds(done.status), answerToCheckedMs: Math.round(done.now - answered) });
  console.log(JSON.stringify(results.at(-1)));
  // Let the drive persist Main's interface before the page is left.
  await new Promise((d) => setTimeout(d, 3000));
  const from = server.log.length;
  const before = await page.eval(() => performance.timeOrigin);
  await page.navigate(`${server.origin}/`);
  for (;;) { try { if ((await page.eval(() => performance.timeOrigin)) !== before) break; } catch {} await new Promise((d) => setTimeout(d, 50)); }
  const warm = await until(page, (s) => !s.busy && s.consent === null && s.status.startsWith("Module checked"));
  events = await page.eval(() => window.__browserCheck);
  const mounting = events.find((e) => e.name === "bar" && /Mounting \d+ archives? of agda-algebras' interfaces, kept/.test(e.text ?? ""))?.t;
  const warmStart = events.find((e) => e.t >= (mounting ?? 0) && e.name === "status" && /^Checking source/.test(e.text ?? ""))?.t;
  const warmReady = events.find((e) => e.name === "bar" && /Agda ready/.test(e.text ?? ""))?.t;
  const asks = events.filter((e) => e.name === "consent" && e.text).length;
  const again = server.log.slice(from).filter((r) => r.url.startsWith("/agda-algebras/interfaces/"));
  results.push({ module, round, visit: "second", load: Number(loadavg()[0].toFixed(2)), asked: asks, archives: again.length,
    agdaReadyMs: warmReady, mountMs: mounting === undefined || warmStart === undefined ? null : Math.round(warmStart - mounting),
    checkS: seconds(warm.status), navigationToCheckedMs: Math.round(warm.now) });
  console.log(JSON.stringify(results.at(-1)));
  await chrome.close(); await server.close();
}
